fn main(){for path in std::env::args().skip(1){let text=std::fs::read_to_string(&path).unwrap();let module=naga::front::wgsl::parse_str(&text).unwrap_or_else(|e|panic!("{}",e.emit_to_string(&text)));naga::valid::Validator::new(naga::valid::ValidationFlags::all(),naga::valid::Capabilities::all()).validate(&module).unwrap_or_else(|e|panic!("{}",e.emit_to_string(&text)));println!("VALID {path}");}}
